          if (!Number.isFinite(v)) continue;
          const x = X(q) - (per * p.ys.length) / 2 + per * k;
          svg.append(
            sv("rect", { x, y: Math.min(Y(v), Y(0)), width: per - 1, height: Math.abs(Y(v) - Y(0)), fill: color }),
          );
